create table public.vtt_boards(table_id uuid primary key references public.dice_tables(id)on delete cascade,created_by uuid not null references auth.users(id)on delete cascade,background_asset text not null default'/assets/nightcrown.png',grid_columns smallint not null default 12 check(grid_columns between 5 and 30),grid_rows smallint not null default 8 check(grid_rows between 5 and 30),fog_enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.vtt_tokens(id uuid primary key default gen_random_uuid(),table_id uuid not null references public.vtt_boards(table_id)on delete cascade,character_id uuid references public.characters(id)on delete cascade,owner_user_id uuid references auth.users(id)on delete cascade,label text not null,x numeric(5,2)not null check(x between 0 and 100),y numeric(5,2)not null check(y between 0 and 100),color text not null default'#d8b96c',visible boolean not null default true,updated_at timestamptz not null default now(),unique(table_id,character_id));
create table public.vtt_fog_cells(table_id uuid not null references public.vtt_boards(table_id)on delete cascade,cell_x smallint not null check(cell_x between 0 and 29),cell_y smallint not null check(cell_y between 0 and 29),revealed boolean not null default false,updated_by uuid not null references auth.users(id),updated_at timestamptz not null default now(),primary key(table_id,cell_x,cell_y));
alter table public.vtt_boards enable row level security;alter table public.vtt_tokens enable row level security;alter table public.vtt_fog_cells enable row level security;create policy "Room members can read VTT boards"on public.vtt_boards for select to authenticated using(public.is_dice_table_member(table_id));create policy "Room members can read VTT tokens"on public.vtt_tokens for select to authenticated using(public.is_dice_table_member(table_id));create policy "Room members can read VTT fog"on public.vtt_fog_cells for select to authenticated using(public.is_dice_table_member(table_id));
create or replace function public.vtt_board_state(target_table_id uuid)returns jsonb language plpgsql security definer set search_path=''stable as $$declare board public.vtt_boards%rowtype;member public.dice_table_members%rowtype;tokens jsonb;fog jsonb;begin select*into member from public.dice_table_members where table_id=target_table_id and user_id=auth.uid();if member.id is null then raise exception'room member required';end if;select*into board from public.vtt_boards where table_id=target_table_id;if board.table_id is null then return jsonb_build_object('board',null,'tokens','[]'::jsonb,'fog','[]'::jsonb,'viewer_role',member.role,'viewer_character_id',member.character_id);end if;select coalesce(jsonb_agg(jsonb_build_object('id',token.id,'character_id',token.character_id,'owner_user_id',token.owner_user_id,'label',token.label,'x',token.x,'y',token.y,'color',token.color,'visible',token.visible,'is_own',token.owner_user_id=auth.uid())order by token.label),'[]'::jsonb)into tokens from public.vtt_tokens token where token.table_id=target_table_id;select coalesce(jsonb_agg(jsonb_build_object('cell_x',cell_x,'cell_y',cell_y,'revealed',revealed)),'[]'::jsonb)into fog from public.vtt_fog_cells where table_id=target_table_id;return jsonb_build_object('board',to_jsonb(board),'tokens',tokens,'fog',fog,'viewer_role',member.role,'viewer_character_id',member.character_id);end;$$;
create or replace function public.ensure_vtt_board(target_table_id uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare member public.dice_table_members%rowtype;board public.vtt_boards%rowtype;entry record;token_index integer:=0;begin select*into member from public.dice_table_members where table_id=target_table_id and user_id=auth.uid();if member.id is null then raise exception'room member required';end if;select*into board from public.vtt_boards where table_id=target_table_id;if board.table_id is null then if member.role<>'dm'then raise exception'dm required';end if;insert into public.vtt_boards(table_id,created_by)values(target_table_id,auth.uid())returning*into board;for entry in select room_member.user_id,room_member.character_id,hero.name from public.dice_table_members room_member join public.characters hero on hero.id=room_member.character_id where room_member.table_id=target_table_id and room_member.role in('dm','player')and room_member.character_id is not null order by room_member.joined_at loop token_index:=token_index+1;insert into public.vtt_tokens(table_id,character_id,owner_user_id,label,x,y,color)values(target_table_id,entry.character_id,entry.user_id,entry.name,10+token_index*8,82,case when token_index%3=1 then'#d8b96c'when token_index%3=2 then'#70a9a1'else'#a77ca8'end)on conflict(table_id,character_id)do nothing;end loop;end if;return public.vtt_board_state(target_table_id);end;$$;
create or replace function public.move_vtt_token(target_table_id uuid,target_token_id uuid,target_x numeric,target_y numeric)returns jsonb language plpgsql security definer set search_path=''as $$declare member public.dice_table_members%rowtype;token public.vtt_tokens%rowtype;begin if target_x not between 0 and 100 or target_y not between 0 and 100 then raise exception'invalid position';end if;select*into member from public.dice_table_members where table_id=target_table_id and user_id=auth.uid();if member.id is null or member.role='spectator'then raise exception'player required';end if;select*into token from public.vtt_tokens where id=target_token_id and table_id=target_table_id for update;if token.id is null then raise exception'token not found';end if;if member.role<>'dm'and token.owner_user_id<>auth.uid()then raise exception'token owner required';end if;update public.vtt_tokens set x=target_x,y=target_y,updated_at=now()where id=token.id;return public.vtt_board_state(target_table_id);end;$$;
create or replace function public.set_vtt_fog_cell(target_table_id uuid,target_cell_x integer,target_cell_y integer,target_revealed boolean)returns jsonb language plpgsql security definer set search_path=''as $$declare member public.dice_table_members%rowtype;board public.vtt_boards%rowtype;begin select*into member from public.dice_table_members where table_id=target_table_id and user_id=auth.uid()and role='dm';if member.id is null then raise exception'dm required';end if;select*into board from public.vtt_boards where table_id=target_table_id;if board.table_id is null then raise exception'board not found';end if;if target_cell_x<0 or target_cell_x>=board.grid_columns or target_cell_y<0 or target_cell_y>=board.grid_rows then raise exception'invalid cell';end if;insert into public.vtt_fog_cells(table_id,cell_x,cell_y,revealed,updated_by)values(target_table_id,target_cell_x,target_cell_y,target_revealed,auth.uid())on conflict(table_id,cell_x,cell_y)do update set revealed=excluded.revealed,updated_by=auth.uid(),updated_at=now();return public.vtt_board_state(target_table_id);end;$$;
revoke all on function public.vtt_board_state(uuid)from public;revoke all on function public.ensure_vtt_board(uuid)from public;revoke all on function public.move_vtt_token(uuid,uuid,numeric,numeric)from public;revoke all on function public.set_vtt_fog_cell(uuid,integer,integer,boolean)from public;grant execute on function public.vtt_board_state(uuid)to authenticated;grant execute on function public.ensure_vtt_board(uuid)to authenticated;grant execute on function public.move_vtt_token(uuid,uuid,numeric,numeric)to authenticated;grant execute on function public.set_vtt_fog_cell(uuid,integer,integer,boolean)to authenticated;alter publication supabase_realtime add table public.vtt_tokens;alter publication supabase_realtime add table public.vtt_fog_cells;
